{
  "rationale": "To ensure that clients in the 10.0.1.0/24 subnet can reach the web server network 10.0.2.0/24 but cannot reach the management network 10.0.99.0/24, we need to configure static routes and access control rules on both routers.",
  "static_routes": [
    {
      "node": "r1",
      "prefix": "10.0.2.0/24",
      "next_hop": "10.0.12.2"
    },
    {
      "node": "r2",
      "prefix": "10.0.2.0/24",
      "next_hop": "10.0.12.1"
    }
  ],
  "access_policy": [
    {
      "node": "r1",
      "src": "10.0.1.0/24",
      "dst": "10.0.99.0/24",
      "action": "deny"
    },
    {
      "node": "r2",
      "src": "10.0.1.0/24",
      "dst": "10.0.99.0/24",
      "action": "deny"
    }
  ]
}
